window.bookSummaryJSON = "<p><i>Two Worlds and in Between: The Best of Caitlín R. Kiernan</i> presents a stunning retrospective of the first 10 years of the author’s work. It is a compilation of more than 200,000 words of short fiction, including many of her most acclaimed stories as well as some of the author’s personal favorites; several previously uncollected, hard-to-find pieces; her sci-fi novella, <i>The Dry Salvages</i>; and a rare collaboration with Poppy Z. Brite.</p>"; 
